  select c2.id, (select tw.i from (values (0,90.53,122.87),(1,35.03,55.4),(2,89.61,52.81),(3,72.93,124.35),(4,113.32,87.71),(5,101.3,112.4),(6,252.94,230.31),(7,51.28,125.58),(8,94.92,147.78),(9,145.9,45.87),(10,143.99,103.0),(11,247.43,196.74),(12,102.68,98.11),(13,108.12,161.42),(14,85.12,135.53),(15,128.82,82.03),(16,78.92,109.6),(17,121.58,60.68),(18,221.12,195.67),(19,105.35,21.33),(20,81.05,31.08),(21,159.3,127.21),(22,70.78,50.67),(23,195.4,122.59),(24,161.59,169.1),(25,109.98,152.57),(26,45.95,74.44),(27,166.47,45.3),(28,239.27,263.97),(29,190.22,160.19),(30,37.13,99.38),(31,78.59,77.08),(32,109.37,83.77),(33,133.17,13.04),(34,72.27,18.78),(35,110.53,129.54),(36,239.67,211.21),(37,148.93,173.56),(38,71.01,105.28),(39,234.11,268.37)) tw(i, x, y)
                  where sqrt(power((c2.id % 540 + 0.5) * 0.5 - tw.x, 2) + power((c2.id / 540 + 0.5) * 0.5 - tw.y, 2)) <= 14
                  order by sqrt(power((c2.id % 540 + 0.5) * 0.5 - tw.x, 2) + power((c2.id / 540 + 0.5) * 0.5 - tw.y, 2)), tw.i limit 1) as idx
    from public.map_cells c2
) t where t.id = c.id;

update public.map_cells c set town_index = f.t from (values (35294,19),(36941,19),(39556,-1),(52608,17),(55240,2),(61835,-1),(67659,2),(73016,26),(75811,-1),(95136,26),(113053,12),(117328,38),(122110,-1),(125042,21),(152051,-1),(172072,29),(187609,-1),(240763,-1),(264028,6)) f(id, t) where c.id = f.id;
